/* ============================================================
   路书 · 工作台  设计令牌
   浅色专业软件风：白底 + 灰阶分层 + 单一蓝色强调
   ============================================================ */
:root{
  --rb-bg:#F6F7F9;          /* 工作台最底层 */
  --rb-surface:#FFFFFF;     /* 面板 */
  --rb-surface-2:#FAFBFC;   /* 次级面 */
  --rb-hover:#F1F3F6;
  --rb-active:#EAF2FF;      /* 选中：淡蓝 */
  --rb-border:#E3E6EB;
  --rb-border-strong:#D2D7DE;
  --rb-text:#1C1F23;
  --rb-text-2:#5A6270;
  --rb-text-3:#8B93A1;
  --rb-text-4:#AEB5C0;
  --rb-hint:#B4BAC4;        /* 占位符 */

  --rb-blue:#2F6BFF;        /* 唯一强调色 */
  --rb-blue-hover:#1E57E8;
  --rb-blue-soft:#EAF2FF;
  --rb-blue-ring:rgba(47,107,255,.14);

  --rb-green:#18975A;
  --rb-green-soft:#E6F6EC;
  --rb-orange:#C9761A;
  --rb-orange-soft:#FDF1E3;
  --rb-red:#D0353F;
  --rb-red-soft:#FCEAEB;

  --rb-r:6px;
  --rb-r-lg:10px;
  --rb-shadow-sm:0 1px 2px rgba(20,25,35,.06);
  --rb-shadow:0 4px 14px rgba(20,25,35,.08);
  --rb-shadow-lg:0 16px 48px rgba(20,25,35,.16);

  --rb-side:264px;
  --rb-aside:360px;
}

.rb{ font:14px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",
     "Microsoft YaHei",sans-serif; color:var(--rb-text); }

/* ---------- 工作台骨架 ---------- */
.rb-app{
  display:flex;
  width:1440px;
  height:900px;
  background:var(--rb-bg);
  border:1px solid var(--rb-border-strong);
  border-radius:12px;
  overflow:hidden;
  box-shadow:var(--rb-shadow-lg);
}
.rb-side{
  width:var(--rb-side);
  flex:0 0 var(--rb-side);
  background:var(--rb-surface-2);
  border-right:1px solid var(--rb-border);
  display:flex;
  flex-direction:column;
  min-height:0;
}
.rb-side-top{ padding:14px 12px 10px; border-bottom:1px solid var(--rb-border); }
.rb-brand{ display:flex; align-items:center; gap:8px; }
.rb-brand-mark{
  width:26px; height:26px; border-radius:7px;
  background:linear-gradient(135deg,#2F6BFF,#5A8BFF);
  color:#fff; font-size:14px; font-weight:700;
  display:flex; align-items:center; justify-content:center;
}
.rb-brand-name{ font-size:15px; font-weight:600; letter-spacing:.2px; }
.rb-brand-sub{ font-size:11px; color:var(--rb-text-3); margin-left:2px; }

.rb-side-body{ flex:1; overflow:auto; padding:8px; min-height:0; }
.rb-side-foot{ border-top:1px solid var(--rb-border); padding:8px; }

.rb-nav-label{
  font-size:11px; letter-spacing:.6px; color:var(--rb-text-4);
  padding:10px 8px 6px; text-transform:uppercase;
}
.rb-nav-item{
  display:flex; align-items:center; gap:9px; height:34px;
  padding:0 8px; border-radius:var(--rb-r);
  font-size:13px; color:var(--rb-text-2); cursor:pointer;
}
.rb-nav-item:hover{ background:var(--rb-hover); color:var(--rb-text); }
.rb-nav-item-on{ background:var(--rb-active); color:var(--rb-blue); font-weight:600; }
.rb-nav-item-on .rb-nav-count{ background:#fff; color:var(--rb-blue); }
.rb-nav-icon{ width:16px; text-align:center; font-size:14px; }
.rb-nav-count{
  margin-left:auto; font-size:11px; min-width:18px; height:18px; padding:0 5px;
  border-radius:9px; background:var(--rb-hover); color:var(--rb-text-3);
  display:flex; align-items:center; justify-content:center;
}

.rb-conv{
  display:flex; flex-direction:column; gap:2px;
  padding:7px 8px; border-radius:var(--rb-r);
  font-size:13px; color:var(--rb-text-2); cursor:pointer;
}
.rb-conv:hover{ background:var(--rb-hover); }
.rb-conv-on{ background:var(--rb-active); }
.rb-conv-title{
  color:var(--rb-text); font-weight:500;
  overflow:hidden; text-overflow:ellipsis; white-space:nowrap;
}
.rb-conv-on .rb-conv-title{ color:var(--rb-blue); }
.rb-conv-meta{ font-size:11px; color:var(--rb-text-4); }

/* ---------- 主区 ---------- */
.rb-main{ flex:1; min-width:0; display:flex; flex-direction:column; background:var(--rb-surface); }
.rb-topbar{
  height:52px; flex:0 0 52px; display:flex; align-items:center; gap:12px;
  padding:0 16px; border-bottom:1px solid var(--rb-border);
}
.rb-crumb{ font-size:12px; color:var(--rb-text-3); }
.rb-crumb-sep{ margin:0 6px; color:var(--rb-text-4); }
.rb-topbar-title{ font-size:14px; font-weight:600; }
.rb-page-body{ flex:1; overflow:auto; padding:16px; min-height:0; }

/* ---------- 通用零件 ---------- */
.rb-btn{
  height:32px; padding:0 12px; border-radius:var(--rb-r);
  border:1px solid var(--rb-border-strong); background:#fff;
  font-size:13px; color:var(--rb-text); display:inline-flex;
  align-items:center; gap:6px; cursor:pointer;
}
.rb-btn:hover{ background:var(--rb-hover); }
.rb-btn-primary{
  background:var(--rb-blue); border-color:var(--rb-blue); color:#fff;
}
.rb-btn-primary:hover{ background:var(--rb-blue-hover); border-color:var(--rb-blue-hover); }
.rb-btn-ghost{ border-color:transparent; background:transparent; color:var(--rb-text-2); }
.rb-btn-ghost:hover{ background:var(--rb-hover); }
.rb-btn-sm{ height:28px; padding:0 10px; font-size:12px; }
.rb-btn-danger{ color:var(--rb-red); border-color:#F0C9CC; }

.rb-input{
  height:32px; width:100%; padding:0 10px;
  border:1px solid var(--rb-border-strong); border-radius:var(--rb-r);
  background:#fff; font-size:13px; color:var(--rb-text); outline:none;
}
.rb-input:focus{ border-color:var(--rb-blue); box-shadow:0 0 0 3px var(--rb-blue-ring); }
.rb-input::placeholder{ color:var(--rb-hint); }
.rb-textarea{
  width:100%; min-height:76px; padding:10px 12px; resize:none;
  border:1px solid var(--rb-border-strong); border-radius:var(--rb-r);
  font:13px/1.7 inherit; color:var(--rb-text); outline:none;
}
.rb-textarea:focus{ border-color:var(--rb-blue); box-shadow:0 0 0 3px var(--rb-blue-ring); }

.rb-card{
  background:#fff; border:1px solid var(--rb-border);
  border-radius:var(--rb-r-lg); padding:14px 16px;
}
.rb-divider{ height:1px; background:var(--rb-border); }

.rb-h1{ font-size:20px; font-weight:650; line-height:1.35; }
.rb-h2{ font-size:15px; font-weight:600; }
.rb-h3{ font-size:13px; font-weight:600; color:var(--rb-text); }
.rb-sub{ font-size:13px; color:var(--rb-text-2); }
.rb-faint{ font-size:12px; color:var(--rb-text-3); }
.rb-num{ font-size:15px; font-weight:650; letter-spacing:-.2px; }

.rb-chip{
  display:inline-flex; align-items:center; height:20px; padding:0 7px;
  border-radius:4px; font-size:11px; font-weight:500;
  background:var(--rb-hover); color:var(--rb-text-2);
}
.rb-chip-blue{ background:var(--rb-blue-soft); color:var(--rb-blue); }
.rb-chip-green{ background:var(--rb-green-soft); color:var(--rb-green); }
.rb-chip-orange{ background:var(--rb-orange-soft); color:var(--rb-orange); }
.rb-chip-red{ background:var(--rb-red-soft); color:var(--rb-red); }

.rb-kbd{
  display:inline-flex; align-items:center; justify-content:center;
  min-width:18px; height:18px; padding:0 4px;
  border:1px solid var(--rb-border-strong); border-bottom-width:2px;
  border-radius:4px; background:#fff;
  font:11px/1 ui-monospace,Consolas,monospace; color:var(--rb-text-3);
}

.rb-hint{
  display:flex; gap:8px; padding:9px 12px; border-radius:var(--rb-r);
  background:var(--rb-blue-soft); border:1px solid #D6E4FF;
  font-size:12px; line-height:1.65; color:#2C4A8A;
}
.rb-hint-warn{ background:var(--rb-orange-soft); border-color:#F4DFC4; color:#8A5714; }
.rb-hint-danger{ background:var(--rb-red-soft); border-color:#F2CDD0; color:#8E2A32; }

/* ---------- 聊天 ---------- */
.rb-chat{ display:flex; flex-direction:column; min-height:0; flex:1; }
.rb-chat-scroll{
  flex:1; overflow:auto; padding:20px 24px 8px;
  display:flex; flex-direction:column; gap:20px; min-height:0;
}
.rb-turn{ display:flex; gap:10px; align-items:flex-start; }
.rb-turn-ai{ align-items:flex-start; }
.rb-avatar{
  width:26px; height:26px; flex:0 0 26px; border-radius:7px;
  display:flex; align-items:center; justify-content:center;
  font-size:13px; font-weight:600;
}
.rb-avatar-me{ background:var(--rb-hover); color:var(--rb-text-2); }
.rb-avatar-ai{ background:linear-gradient(135deg,#2F6BFF,#5A8BFF); color:#fff; }
.rb-bubble-user{
  max-width:640px; padding:9px 13px; border-radius:8px;
  background:var(--rb-hover); color:var(--rb-text);
  font-size:13px; line-height:1.7;
}
.rb-answer{ flex:1; min-width:0; font-size:13px; line-height:1.85; color:var(--rb-text); }
.rb-answer p{ margin:0 0 10px; }
.rb-answer p:last-child{ margin-bottom:0; }
.rb-answer b{ font-weight:600; }
.rb-answer ol{ margin:0 0 10px; padding-left:20px; }
.rb-answer li{ margin-bottom:4px; }

.rb-cite{
  margin-top:10px; padding:7px 10px;
  border-left:2px solid var(--rb-blue); background:var(--rb-surface-2);
  border-radius:0 4px 4px 0; font-size:11.5px; color:var(--rb-text-2);
}
.rb-cite b{ color:var(--rb-text); font-weight:600; }

.rb-tool{
  display:flex; align-items:center; gap:8px; height:28px; margin-bottom:10px;
  font-size:12px; color:var(--rb-text-3);
}
.rb-tool-dot{
  width:14px; height:14px; border-radius:7px;
  border:2px solid var(--rb-blue); border-top-color:transparent;
  animation:rb-spin .8s linear infinite;
}
@keyframes rb-spin{ to{ transform:rotate(360deg); } }
.rb-cursor::after{
  content:""; display:inline-block; width:2px; height:14px;
  background:var(--rb-blue); margin-left:2px; vertical-align:-2px;
  animation:rb-blink 1s steps(2) infinite;
}
@keyframes rb-blink{ 50%{ opacity:0; } }

.rb-uncovered{
  max-width:640px; padding:12px 14px; border-radius:8px;
  background:var(--rb-orange-soft); border:1px solid #F4DFC4;
  font-size:13px; line-height:1.75; color:#8A5714;
}

.rb-actions{ display:flex; gap:6px; margin-top:10px; }
.rb-chipbtn{
  display:inline-flex; align-items:center; gap:5px; height:24px; padding:0 8px;
  border-radius:5px; border:1px solid var(--rb-border); background:#fff;
  font-size:11.5px; color:var(--rb-text-2); cursor:pointer;
}
.rb-chipbtn:hover{ background:var(--rb-hover); }

.rb-composer{
  padding:10px 24px 14px; border-top:1px solid var(--rb-border);
  background:var(--rb-surface);
}
.rb-composer-box{
  border:1px solid var(--rb-border-strong); border-radius:var(--rb-r-lg);
  background:#fff; padding:10px 12px;
  box-shadow:0 1px 0 rgba(20,25,35,.02);
}
.rb-composer-box:focus-within{
  border-color:var(--rb-blue); box-shadow:0 0 0 3px var(--rb-blue-ring);
}
.rb-composer ta{ display:block; }
.rb-suggest{
  display:inline-flex; align-items:center; height:24px; padding:0 9px;
  border:1px solid var(--rb-border); border-radius:12px;
  font-size:12px; color:var(--rb-text-2); cursor:pointer;
}
.rb-suggest:hover{ border-color:var(--rb-blue); color:var(--rb-blue); background:var(--rb-blue-soft); }

/* ---------- 右侧面板 ---------- */
.rb-aside{
  width:var(--rb-aside); flex:0 0 var(--rb-aside);
  background:var(--rb-surface-2); border-left:1px solid var(--rb-border);
  display:flex; flex-direction:column; min-height:0;
}
.rb-aside-tabs{ display:flex; gap:2px; padding:8px 8px 0; border-bottom:1px solid var(--rb-border); }
.rb-aside-tab{
  height:32px; padding:0 10px; border-radius:var(--rb-r) var(--rb-r) 0 0;
  font-size:12.5px; color:var(--rb-text-3); cursor:pointer;
  display:flex; align-items:center; gap:6px;
}
.rb-aside-tab:hover{ color:var(--rb-text-2); background:var(--rb-hover); }
.rb-aside-tab-on{
  color:var(--rb-blue); font-weight:600;
  box-shadow:inset 0 -2px 0 var(--rb-blue); background:#fff;
}
.rb-aside-body{ flex:1; overflow:auto; padding:12px; min-height:0; }

.rb-src{
  display:flex; flex-direction:column; gap:4px;
  padding:10px; border-radius:var(--rb-r); background:#fff;
  border:1px solid var(--rb-border); margin-bottom:8px; cursor:pointer;
}
.rb-src:hover{ border-color:var(--rb-blue); box-shadow:var(--rb-shadow-sm); }
.rb-src-on{ border-color:var(--rb-blue); box-shadow:0 0 0 3px var(--rb-blue-ring); }
.rb-src-title{ font-size:12.5px; font-weight:600; color:var(--rb-text); }
.rb-src-meta{ font-size:11px; color:var(--rb-text-3); }
.rb-src-quote{
  font-size:11.5px; line-height:1.7; color:var(--rb-text-2);
  padding-left:8px; border-left:2px solid var(--rb-border-strong);
}

.rb-group{
  border:1px solid var(--rb-border); border-radius:var(--rb-r);
  background:#fff; margin-bottom:8px; overflow:hidden;
}
.rb-group-head{
  display:flex; align-items:center; gap:8px; height:36px; padding:0 10px;
  font-size:12.5px; font-weight:600; cursor:pointer;
}
.rb-group-head:hover{ background:var(--rb-hover); }
.rb-group-body{ padding:8px 10px 10px; border-top:1px solid var(--rb-border); }
.rb-doc{
  display:flex; align-items:center; gap:7px; height:26px;
  font-size:12px; color:var(--rb-text-2); cursor:pointer;
}
.rb-doc:hover{ color:var(--rb-blue); }

.rb-kpi{ display:flex; flex-direction:column; gap:2px; }
.rb-kpi-num{ font-size:21px; font-weight:650; letter-spacing:-.4px; }
.rb-kpi-label{ font-size:11.5px; color:var(--rb-text-3); }

/* ---------- 表格 ---------- */
.rb-table{ width:100%; border-collapse:collapse; font-size:12.5px; }
.rb-table th{
  text-align:left; font-weight:600; font-size:11.5px; letter-spacing:.3px;
  color:var(--rb-text-3); background:var(--rb-surface-2);
  padding:9px 12px; border-bottom:1px solid var(--rb-border); white-space:nowrap;
}
.rb-table td{
  padding:11px 12px; border-bottom:1px solid var(--rb-border);
  color:var(--rb-text-2); vertical-align:middle;
}
.rb-table tr:hover td{ background:var(--rb-surface-2); }
.rb-table td:first-child{ color:var(--rb-text); font-weight:500; }
.rb-mono{ font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace; color:var(--rb-text-2); }

/* ---------- 工具条 / 分页 ---------- */
.rb-toolbar{
  display:flex; align-items:center; gap:8px; padding:10px 12px;
  border-bottom:1px solid var(--rb-border); background:#fff;
}
.rb-pager{ display:flex; align-items:center; gap:6px; padding:10px 12px; }
.rb-page-no{
  min-width:26px; height:26px; padding:0 6px; border-radius:5px;
  border:1px solid var(--rb-border); background:#fff;
  font-size:12px; color:var(--rb-text-2);
  display:inline-flex; align-items:center; justify-content:center; cursor:pointer;
}
.rb-page-no-on{ border-color:var(--rb-blue); color:var(--rb-blue); background:var(--rb-blue-soft); font-weight:600; }

/* ---------- 登录 ---------- */
.rb-login{
  width:1440px; height:900px; display:flex; overflow:hidden;
  background:#fff; border:1px solid var(--rb-border-strong); border-radius:12px;
  box-shadow:var(--rb-shadow-lg);
}
.rb-login-left{
  flex:1; background:linear-gradient(160deg,#EEF3FF,#F7F9FC 58%,#F6F7F9);
  padding:56px 56px; display:flex; flex-direction:column; justify-content:space-between;
}
.rb-login-right{
  width:440px; flex:0 0 440px; padding:64px 48px;
  display:flex; flex-direction:column; justify-content:center;
}
.rb-feat{ display:flex; gap:10px; align-items:flex-start; margin-bottom:14px; }
.rb-feat-dot{
  width:6px; height:6px; border-radius:3px; background:var(--rb-blue);
  margin-top:8px; flex:0 0 6px;
}
.rb-card-lg{
  background:#fff; border:1px solid var(--rb-border-strong);
  border-radius:var(--rb-r-lg); box-shadow:var(--rb-shadow);
}

