  font-size:13px; line-height:1.7;
}
.rb-answer{ flex:1; min-width:0; font-size:13px; line-height:1.85; color:var(--rb-text); }
.rb-answer p{ margin:0 0 10px; }
.rb-answer p:last-child{ margin-bottom:0; }
.rb-answer b{ font-weight:600; }
.rb-answer ol{ margin:0 0 10px; padding-left:20px; }
.rb-answer li{ margin-bottom:4px; }

.rb-cite{
  margin-top:10px; padding:7px 10px;
  border-left:2px solid var(--rb-blue); background:var(--rb-surface-2);
  border-radius:0 4px 4px 0; font-size:11.5px; color:var(--rb-text-2);
}
.rb-cite b{ color:var(--rb-text); font-weight:600; }

.rb-tool{
  display:flex; align-items:center; gap:8px; height:28px; margin-bottom:10px;
  font-size:12px; color:var(--rb-text-3);
}
