  width:14px; height:14px; border-radius:7px;
  border:2px solid var(--rb-blue); border-top-color:transparent;
  animation:rb-spin .8s linear infinite;
}
@keyframes rb-spin{ to{ transform:rotate(360deg); } }
.rb-cursor::after{
  content:""; display:inline-block; width:2px; height:14px;
  background:var(--rb-blue); margin-left:2px; vertical-align:-2px;
  animation:rb-blink 1s steps(2) infinite;
}
@keyframes rb-blink{ 50%{ opacity:0; } }

.rb-uncovered{
  max-width:640px; padding:12px 14px; border-radius:8px;
  background:var(--rb-orange-soft); border:1px solid #F4DFC4;
