  display:flex; align-items:center; gap:8px; height:36px; padding:0 10px;
  font-size:12.5px; font-weight:600; cursor:pointer;
}
.rb-group-head:hover{ background:var(--rb-hover); }
.rb-group-body{ padding:8px 10px 10px; border-top:1px solid var(--rb-border); }
.rb-doc{
  display:flex; align-items:center; gap:7px; height:26px;
  font-size:12px; color:var(--rb-text-2); cursor:pointer;
}
.rb-doc:hover{ color:var(--rb-blue); }

.rb-kpi{ display:flex; flex-direction:column; gap:2px; }
.rb-kpi-num{ font-size:21px; font-weight:650; letter-spacing:-.4px; }
