.rb-feat-dot{
  width:6px; height:6px; border-radius:3px; background:var(--rb-blue);
  margin-top:8px; flex:0 0 6px;
}
.rb-card-lg{
  background:#fff; border:1px solid var(--rb-border-strong);
  border-radius:var(--rb-r-lg); box-shadow:var(--rb-shadow);
